-- ProcuChain persistence schema: first governed procurement slice.
--
-- Conventions:
--   * UUID primary keys generated by the application.
--   * timestamptz for instants.
--   * enum-like values are constrained text columns.
--   * evidence-bearing rows carry tenant_id and are protected from deletion.
--   * document version content and audit events are append-only.

CREATE TABLE tenants (
    id uuid PRIMARY KEY,
    name text NOT NULL CHECK (btrim(name) <> '')
);

CREATE TABLE users (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants (id),
    display_name text NOT NULL CHECK (btrim(display_name) <> ''),
    status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
    UNIQUE (tenant_id, id)
);

CREATE TABLE committees (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants (id),
    name text NOT NULL CHECK (btrim(name) <> ''),
    UNIQUE (tenant_id, id)
);

CREATE TABLE documents (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants (id),
    document_type text NOT NULL CHECK (
        document_type IN (
            'ppmp',
            'annual_procurement_plan',
            'bac_resolution',
            'contract',
            'other'
        )
    ),
    title text NOT NULL CHECK (btrim(title) <> ''),
    business_id text,
    current_version_id uuid,
    row_version bigint NOT NULL DEFAULT 0 CHECK (row_version >= 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, business_id)
);

CREATE TABLE document_versions (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    document_id uuid NOT NULL,
    version_number integer NOT NULL CHECK (version_number > 0),
    status text NOT NULL CHECK (
        status IN (
            'draft',
            'in_review',
            'approved',
            'signed',
            'issued',
            'rejected',
            'superseded',
            'withdrawn',
            'archived'
        )
    ),
    content jsonb NOT NULL CHECK (jsonb_typeof(content) = 'object'),
    content_hash text NOT NULL CHECK (content_hash ~ '^[0-9a-f]{64}$'),
    template_id text NOT NULL CHECK (btrim(template_id) <> ''),
    template_version text NOT NULL CHECK (btrim(template_version) <> ''),
    template_authority_ref text NOT NULL CHECK (btrim(template_authority_ref) <> ''),
    schema_id text NOT NULL CHECK (btrim(schema_id) <> ''),
    schema_version text NOT NULL CHECK (btrim(schema_version) <> ''),
    rule_pack_snapshot_id uuid NOT NULL,
    rule_pack_version_label text NOT NULL CHECK (btrim(rule_pack_version_label) <> ''),
    rule_pack_manifest_hash text NOT NULL CHECK (rule_pack_manifest_hash ~ '^[0-9a-f]{64}$'),
    author_id uuid NOT NULL,
    authored_at timestamptz NOT NULL,
    correction_of uuid,
    supersedes uuid,
    row_version bigint NOT NULL DEFAULT 0 CHECK (row_version >= 0),
    UNIQUE (tenant_id, id),
    UNIQUE (document_id, version_number),
    FOREIGN KEY (tenant_id, document_id) REFERENCES documents (tenant_id, id),
    FOREIGN KEY (tenant_id, author_id) REFERENCES users (tenant_id, id),
    FOREIGN KEY (tenant_id, correction_of) REFERENCES document_versions (tenant_id, id),
    FOREIGN KEY (tenant_id, supersedes) REFERENCES document_versions (tenant_id, id)
);

ALTER TABLE documents
    ADD CONSTRAINT documents_current_version_fk
    FOREIGN KEY (current_version_id) REFERENCES document_versions (id)
    DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE approvals (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    version_id uuid NOT NULL,
    content_hash text NOT NULL CHECK (content_hash ~ '^[0-9a-f]{64}$'),
    approver_id uuid NOT NULL,
    approver_role text NOT NULL CHECK (
        approver_role IN (
            'end_user',
            'end_user_head',
            'bac_chairperson',
            'bac_vice_chairperson',
            'bac_member',
            'hope',
            'secretariat',
            'records_officer',
            'system'
        )
    ),
    approver_name text NOT NULL CHECK (btrim(approver_name) <> ''),
    decision text NOT NULL CHECK (decision IN ('approved', 'rejected', 'returned', 'abstained')),
    decided_at timestamptz NOT NULL,
    authority_ref text NOT NULL CHECK (btrim(authority_ref) <> ''),
    grounds text,
    status text NOT NULL CHECK (status IN ('active', 'superseded', 'invalidated', 'withdrawn')),
    row_version bigint NOT NULL DEFAULT 0 CHECK (row_version >= 0),
    UNIQUE (tenant_id, id),
    FOREIGN KEY (tenant_id, version_id) REFERENCES document_versions (tenant_id, id),
    FOREIGN KEY (tenant_id, approver_id) REFERENCES users (tenant_id, id)
);

CREATE TABLE bac_resolutions (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    version_id uuid NOT NULL,
    version_hash text NOT NULL CHECK (version_hash ~ '^[0-9a-f]{64}$'),
    committee_id uuid NOT NULL,
    resolution_number text NOT NULL CHECK (btrim(resolution_number) <> ''),
    outcome text NOT NULL CHECK (outcome IN ('recommended', 'not_recommended', 'no_decision')),
    quorum_required integer NOT NULL CHECK (quorum_required > 0),
    resolved_at timestamptz NOT NULL,
    status text NOT NULL CHECK (status IN ('active', 'superseded', 'invalidated')),
    row_version bigint NOT NULL DEFAULT 0 CHECK (row_version >= 0),
    UNIQUE (tenant_id, id),
    FOREIGN KEY (tenant_id, version_id) REFERENCES document_versions (tenant_id, id),
    FOREIGN KEY (tenant_id, committee_id) REFERENCES committees (tenant_id, id)
);

CREATE TABLE bac_resolution_members (
    tenant_id uuid NOT NULL,
    resolution_id uuid NOT NULL,
    user_id uuid NOT NULL,
    seat text NOT NULL CHECK (seat IN ('chairperson', 'vice_chairperson', 'member')),
    display_name text NOT NULL CHECK (btrim(display_name) <> ''),
    ordinal integer NOT NULL CHECK (ordinal >= 0),
    PRIMARY KEY (resolution_id, user_id),
    FOREIGN KEY (tenant_id, resolution_id) REFERENCES bac_resolutions (tenant_id, id),
    FOREIGN KEY (tenant_id, user_id) REFERENCES users (tenant_id, id)
);

CREATE TABLE bac_resolution_attendance (
    tenant_id uuid NOT NULL,
    resolution_id uuid NOT NULL,
    user_id uuid NOT NULL,
    PRIMARY KEY (resolution_id, user_id),
    FOREIGN KEY (tenant_id, resolution_id) REFERENCES bac_resolutions (tenant_id, id),
    FOREIGN KEY (resolution_id, user_id)
        REFERENCES bac_resolution_members (resolution_id, user_id)
);

CREATE TABLE bac_resolution_votes (
    tenant_id uuid NOT NULL,
    resolution_id uuid NOT NULL,
    user_id uuid NOT NULL,
    vote text NOT NULL CHECK (vote IN ('recommend', 'do_not_recommend', 'abstain')),
    PRIMARY KEY (resolution_id, user_id),
    FOREIGN KEY (tenant_id, resolution_id) REFERENCES bac_resolutions (tenant_id, id),
    FOREIGN KEY (resolution_id, user_id)
        REFERENCES bac_resolution_members (resolution_id, user_id)
);

CREATE TABLE signature_requests (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    version_id uuid NOT NULL,
    content_hash text NOT NULL CHECK (content_hash ~ '^[0-9a-f]{64}$'),
    signer_id uuid NOT NULL,
    signer_role text NOT NULL CHECK (
        signer_role IN (
            'end_user',
            'end_user_head',
            'bac_chairperson',
            'bac_vice_chairperson',
            'bac_member',
            'hope',
            'secretariat',
            'records_officer',
            'system'
        )
    ),
    signer_name text NOT NULL CHECK (btrim(signer_name) <> ''),
    purpose text NOT NULL CHECK (purpose IN ('execution', 'attestation', 'approval')),
    method text NOT NULL CHECK (
        method IN (
            'wet_signature',
            'advanced_electronic_signature',
            'qualified_electronic_signature'
        )
    ),
    declaration text NOT NULL CHECK (btrim(declaration) <> ''),
    requested_at timestamptz NOT NULL,
    deadline timestamptz NOT NULL,
    status text NOT NULL CHECK (
        status IN ('requested', 'signed', 'declined', 'verification_failed', 'cancelled', 'expired', 'superseded')
    ),
    row_version bigint NOT NULL DEFAULT 0 CHECK (row_version >= 0),
    CHECK (deadline > requested_at),
    UNIQUE (tenant_id, id),
    FOREIGN KEY (tenant_id, version_id) REFERENCES document_versions (tenant_id, id),
    FOREIGN KEY (tenant_id, signer_id) REFERENCES users (tenant_id, id)
);

CREATE TABLE signatures (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    request_id uuid NOT NULL,
    version_id uuid NOT NULL,
    content_hash text NOT NULL CHECK (content_hash ~ '^[0-9a-f]{64}$'),
    signer_id uuid NOT NULL,
    signer_role text NOT NULL CHECK (
        signer_role IN (
            'end_user',
            'end_user_head',
            'bac_chairperson',
            'bac_vice_chairperson',
            'bac_member',
            'hope',
            'secretariat',
            'records_officer',
            'system'
        )
    ),
    signer_name text NOT NULL CHECK (btrim(signer_name) <> ''),
    method text NOT NULL CHECK (
        method IN (
            'wet_signature',
            'advanced_electronic_signature',
            'qualified_electronic_signature'
        )
    ),
    signed_at timestamptz NOT NULL,
    provider_transaction text NOT NULL CHECK (btrim(provider_transaction) <> ''),
    credential_ref text NOT NULL CHECK (btrim(credential_ref) <> ''),
    signed_artifact_hash text NOT NULL CHECK (signed_artifact_hash ~ '^[0-9a-f]{64}$'),
    validation text NOT NULL CHECK (
        validation IN ('valid', 'verification_failed', 'revoked', 'expired', 'signer_mismatch')
    ),
    status text NOT NULL CHECK (status IN ('valid', 'invalidated', 'failed')),
    row_version bigint NOT NULL DEFAULT 0 CHECK (row_version >= 0),
    UNIQUE (tenant_id, id),
    FOREIGN KEY (tenant_id, request_id) REFERENCES signature_requests (tenant_id, id),
    FOREIGN KEY (tenant_id, version_id) REFERENCES document_versions (tenant_id, id),
    FOREIGN KEY (tenant_id, signer_id) REFERENCES users (tenant_id, id)
);

CREATE TABLE issuances (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    version_id uuid NOT NULL,
    version_hash text NOT NULL CHECK (version_hash ~ '^[0-9a-f]{64}$'),
    issuer_id uuid NOT NULL,
    issuer_role text NOT NULL CHECK (
        issuer_role IN (
            'end_user',
            'end_user_head',
            'bac_chairperson',
            'bac_vice_chairperson',
            'bac_member',
            'hope',
            'secretariat',
            'records_officer',
            'system'
        )
    ),
    issuer_name text NOT NULL CHECK (btrim(issuer_name) <> ''),
    authority_ref text NOT NULL CHECK (btrim(authority_ref) <> ''),
    issued_at timestamptz NOT NULL,
    manifest_hash text NOT NULL CHECK (manifest_hash ~ '^[0-9a-f]{64}$'),
    status text NOT NULL CHECK (status IN ('active', 'superseded', 'withdrawn')),
    row_version bigint NOT NULL DEFAULT 0 CHECK (row_version >= 0),
    UNIQUE (tenant_id, id),
    FOREIGN KEY (tenant_id, version_id) REFERENCES document_versions (tenant_id, id),
    FOREIGN KEY (tenant_id, issuer_id) REFERENCES users (tenant_id, id)
);

CREATE TABLE issuance_artifacts (
    tenant_id uuid NOT NULL,
    issuance_id uuid NOT NULL,
    artifact_id uuid NOT NULL,
    media_type text NOT NULL CHECK (btrim(media_type) <> ''),
    hash text NOT NULL CHECK (hash ~ '^[0-9a-f]{64}$'),
    ordinal integer NOT NULL CHECK (ordinal >= 0),
    PRIMARY KEY (issuance_id, artifact_id),
    FOREIGN KEY (tenant_id, issuance_id) REFERENCES issuances (tenant_id, id)
);

CREATE TABLE issuance_recipients (
    tenant_id uuid NOT NULL,
    issuance_id uuid NOT NULL,
    recipient_id uuid NOT NULL,
    kind text NOT NULL CHECK (kind IN ('internal_office', 'external_party', 'public')),
    name text NOT NULL CHECK (btrim(name) <> ''),
    address text,
    channel text NOT NULL CHECK (channel IN ('portal', 'email', 'printed_copy', 'pe_website', 'philgeps')),
    acknowledgement_required boolean NOT NULL,
    ordinal integer NOT NULL CHECK (ordinal >= 0),
    PRIMARY KEY (issuance_id, recipient_id),
    FOREIGN KEY (tenant_id, issuance_id) REFERENCES issuances (tenant_id, id),
    CHECK (NOT (kind = 'public' AND acknowledgement_required))
);

CREATE TABLE distributions (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    issuance_id uuid NOT NULL,
    recipient_id uuid NOT NULL,
    version_id uuid NOT NULL,
    channel text NOT NULL CHECK (channel IN ('portal', 'email', 'printed_copy', 'pe_website', 'philgeps')),
    acknowledgement_required boolean NOT NULL,
    status text NOT NULL CHECK (
        status IN ('planned', 'delivered', 'failed', 'acknowledged', 'superseded')
    ),
    row_version bigint NOT NULL DEFAULT 0 CHECK (row_version >= 0),
    UNIQUE (tenant_id, id),
    FOREIGN KEY (tenant_id, issuance_id) REFERENCES issuances (tenant_id, id),
    FOREIGN KEY (issuance_id, recipient_id)
        REFERENCES issuance_recipients (issuance_id, recipient_id),
    FOREIGN KEY (tenant_id, version_id) REFERENCES document_versions (tenant_id, id)
);

CREATE TABLE delivery_attempts (
    id bigserial PRIMARY KEY,
    tenant_id uuid NOT NULL,
    distribution_id uuid NOT NULL,
    attempted_at timestamptz NOT NULL,
    channel_ref text NOT NULL CHECK (btrim(channel_ref) <> ''),
    result text NOT NULL CHECK (result IN ('delivered', 'failed')),
    failure_reason text,
    ordinal integer NOT NULL CHECK (ordinal >= 0),
    UNIQUE (distribution_id, ordinal),
    FOREIGN KEY (tenant_id, distribution_id) REFERENCES distributions (tenant_id, id),
    CHECK (
        (result = 'delivered' AND failure_reason IS NULL)
        OR (result = 'failed' AND failure_reason IS NOT NULL AND btrim(failure_reason) <> '')
    )
);

CREATE TABLE acknowledgements (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    distribution_id uuid NOT NULL,
    issuance_id uuid NOT NULL,
    version_id uuid NOT NULL,
    artifact_hash text NOT NULL CHECK (artifact_hash ~ '^[0-9a-f]{64}$'),
    acknowledged_by uuid NOT NULL,
    acknowledged_at timestamptz NOT NULL,
    method text NOT NULL CHECK (method IN ('portal', 'email', 'signed_receipt', 'other')),
    method_other text,
    declaration text,
    status text NOT NULL CHECK (status IN ('active', 'invalidated')),
    row_version bigint NOT NULL DEFAULT 0 CHECK (row_version >= 0),
    UNIQUE (tenant_id, id),
    FOREIGN KEY (tenant_id, distribution_id) REFERENCES distributions (tenant_id, id),
    FOREIGN KEY (tenant_id, issuance_id) REFERENCES issuances (tenant_id, id),
    FOREIGN KEY (tenant_id, version_id) REFERENCES document_versions (tenant_id, id),
    FOREIGN KEY (issuance_id, acknowledged_by)
        REFERENCES issuance_recipients (issuance_id, recipient_id),
    CHECK (
        (method = 'other' AND method_other IS NOT NULL AND btrim(method_other) <> '')
        OR (method <> 'other' AND method_other IS NULL)
    )
);

CREATE TABLE audit_events (
    tenant_id uuid NOT NULL REFERENCES tenants (id),
    seq bigint NOT NULL CHECK (seq > 0),
    event_type text NOT NULL CHECK (btrim(event_type) <> ''),
    actor_id uuid,
    subject_kind text NOT NULL CHECK (btrim(subject_kind) <> ''),
    subject_id text NOT NULL CHECK (btrim(subject_id) <> ''),
    occurred_at timestamptz NOT NULL,
    details jsonb NOT NULL CHECK (jsonb_typeof(details) = 'object'),
    previous_hash text NOT NULL CHECK (previous_hash ~ '^[0-9a-f]{64}$'),
    event_hash text NOT NULL CHECK (event_hash ~ '^[0-9a-f]{64}$'),
    PRIMARY KEY (tenant_id, seq),
    UNIQUE (tenant_id, event_hash),
    FOREIGN KEY (tenant_id, actor_id) REFERENCES users (tenant_id, id)
);

CREATE TABLE outbox_events (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants (id),
    aggregate_kind text NOT NULL CHECK (btrim(aggregate_kind) <> ''),
    aggregate_id uuid NOT NULL,
    event_type text NOT NULL CHECK (btrim(event_type) <> ''),
    payload jsonb NOT NULL,
    occurred_at timestamptz NOT NULL,
    published_at timestamptz,
    attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0)
);

CREATE TABLE idempotency_records (
    tenant_id uuid NOT NULL REFERENCES tenants (id),
    idempotency_key text NOT NULL CHECK (btrim(idempotency_key) <> ''),
    command_type text NOT NULL CHECK (btrim(command_type) <> ''),
    request_hash text NOT NULL,
    response_status integer,
    response_body jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (tenant_id, idempotency_key)
);

CREATE INDEX documents_type_idx ON documents (tenant_id, document_type);
CREATE INDEX document_versions_document_idx ON document_versions (document_id, version_number);
CREATE INDEX approvals_version_idx ON approvals (tenant_id, version_id, status);
CREATE INDEX bac_resolutions_version_idx ON bac_resolutions (tenant_id, version_id, status);
CREATE INDEX signature_requests_version_idx ON signature_requests (tenant_id, version_id, status);
CREATE INDEX signatures_version_idx ON signatures (tenant_id, version_id);
CREATE INDEX issuances_version_idx ON issuances (tenant_id, version_id, status);
CREATE INDEX distributions_issuance_idx ON distributions (issuance_id);
CREATE INDEX acknowledgements_distribution_idx ON acknowledgements (distribution_id);
CREATE INDEX audit_events_occurred_idx ON audit_events (tenant_id, occurred_at);
CREATE INDEX outbox_pending_idx ON outbox_events (occurred_at) WHERE published_at IS NULL;

-- Audit events are append-only. A separate database role is also recommended
-- in production; the trigger protects against accidental application writes.
CREATE FUNCTION reject_audit_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'audit_events are append-only';
END;
$$;

CREATE TRIGGER audit_events_no_mutation
BEFORE UPDATE OR DELETE ON audit_events
FOR EACH ROW EXECUTE FUNCTION reject_audit_mutation();

-- Version content, lineage, and authorship never change after creation.
-- Status transitions and the concurrency counter remain allowed.
CREATE FUNCTION protect_document_version() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'document_versions cannot be deleted';
    END IF;
    IF NEW.document_id <> OLD.document_id
        OR NEW.version_number <> OLD.version_number
        OR NEW.content IS DISTINCT FROM OLD.content
        OR NEW.content_hash <> OLD.content_hash
        OR NEW.template_id <> OLD.template_id
        OR NEW.template_version <> OLD.template_version
        OR NEW.template_authority_ref <> OLD.template_authority_ref
        OR NEW.schema_id <> OLD.schema_id
        OR NEW.schema_version <> OLD.schema_version
        OR NEW.rule_pack_snapshot_id <> OLD.rule_pack_snapshot_id
        OR NEW.rule_pack_version_label <> OLD.rule_pack_version_label
        OR NEW.rule_pack_manifest_hash <> OLD.rule_pack_manifest_hash
        OR NEW.author_id <> OLD.author_id
        OR NEW.authored_at <> OLD.authored_at
        OR NEW.correction_of IS DISTINCT FROM OLD.correction_of
        OR NEW.supersedes IS DISTINCT FROM OLD.supersedes
    THEN
        RAISE EXCEPTION 'document version content is immutable';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER document_versions_immutable
BEFORE UPDATE OR DELETE ON document_versions
FOR EACH ROW EXECUTE FUNCTION protect_document_version();

-- Evidence rows are superseded or invalidated, never deleted.
CREATE FUNCTION reject_evidence_delete() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION '% rows cannot be deleted', TG_TABLE_NAME;
END;
$$;

CREATE TRIGGER approvals_no_delete
BEFORE DELETE ON approvals
FOR EACH ROW EXECUTE FUNCTION reject_evidence_delete();

CREATE TRIGGER bac_resolutions_no_delete
BEFORE DELETE ON bac_resolutions
FOR EACH ROW EXECUTE FUNCTION reject_evidence_delete();

CREATE TRIGGER signature_requests_no_delete
BEFORE DELETE ON signature_requests
FOR EACH ROW EXECUTE FUNCTION reject_evidence_delete();

CREATE TRIGGER signatures_no_delete
BEFORE DELETE ON signatures
FOR EACH ROW EXECUTE FUNCTION reject_evidence_delete();

CREATE TRIGGER issuances_no_delete
BEFORE DELETE ON issuances
FOR EACH ROW EXECUTE FUNCTION reject_evidence_delete();

CREATE TRIGGER distributions_no_delete
BEFORE DELETE ON distributions
FOR EACH ROW EXECUTE FUNCTION reject_evidence_delete();

CREATE TRIGGER acknowledgements_no_delete
BEFORE DELETE ON acknowledgements
FOR EACH ROW EXECUTE FUNCTION reject_evidence_delete();
